mapper.update:
UPDATE sq_runtime_admission_slot
SET turn_id = #{turnId}
WHERE user_id = #{userId}
  AND binding_id = #{bindingId}
  AND command_id = #{commandId}
  AND status = 'ACTIVE'
  AND (turn_id IS NULL OR turn_id = #{turnId})

mapper.select:
SELECT native_turn_id
FROM sq_command
WHERE user_id = #{userId}
  AND command_id = #{commandId}
  AND native_turn_id IS NOT NULL
LIMIT 1

SELECT last_ended_turn_id
FROM sq_runtime_binding
WHERE user_id = #{userId}
  AND binding_id = #{bindingId}

SELECT drift.pool_key FROM ( SELECT c.pool_key FROM sq_runtime_admission_counter c LEFT JOIN sq_runtime_admission_slot s ON s.status = 'ACTIVE' AND ( c.pool_key = 'GLOBAL' OR c.pool_key = CONCAT('USER:', s.user_id) ) GROUP BY c.pool_key, c.active_count HAVING c.active_count <> COUNT(s.binding_id)
UNION
SELECT CONCAT('USER:', s.user_id) AS pool_key FROM sq_runtime_admission_slot s LEFT JOIN sq_runtime_admission_counter c ON c.pool_key = CONCAT('USER:', s.user_id) WHERE s.status = 'ACTIVE' AND c.pool_key IS NULL ) drift LIMIT #{limit}

mapper.update:
UPDATE sq_runtime_admission_slot
SET status = 'RELEASED',
    released_at = UTC_TIMESTAMP(3)
WHERE user_id = #{userId}
  AND binding_id = #{bindingId}
  AND command_id = #{commandId}
  AND status = 'ACTIVE'

UPDATE sq_runtime_admission_counter
SET active_count = active_count + 1
WHERE pool_key = #{poolKey}
